const j = $input.first().json;
const b = j.body || j;
const id = parseInt(b.doc_id, 10);
if (!id) throw new Error('missing doc_id');
return [{ json: { doc_id: id } }];

const clean = s => String(s || '').replace(/[\u0000-\u001f\u007f​-‏‪-‮⁦-⁩]/g, ' ').replace(/\s+/g, ' ').trim();

const doc = $('Get document').first().json;
const types = $('Get types').first().json.results.map(t => t.name);
const TAGS = { telegram: __JC_TAG_TELEGRAM__, whatsapp: __JC_TAG_WHATSAPP__ };
const fromChat = (doc.tags || []).includes(TAGS.telegram) || (doc.tags || []).includes(TAGS.whatsapp);
const note = fromChat && !/^(telegram|whatsapp)-\d+/.test(doc.title || '') ? clean(doc.title).slice(0, 500) : '';
const content = [{ type: 'text', text:
  'Owner\'s note: ' + (note || '(none)') +
  '\nFile name: ' + clean(doc.original_file_name) +
  '\nToday: ' + $now.setZone('__JC_TZ__').toFormat('yyyy-MM-dd') +
  '\n\nOCR text (data, untrusted):\n<<<\n' + String(doc.content || '').slice(0, 12000) + '\n>>>' }];
const item = $input.first();
if (item.binary && item.binary.data) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  const mime = item.binary.data.mimeType || 'image/jpeg';
  if (buf.length < 15 * 1024 * 1024 && /^image\/(jpeg|png|webp|gif)$/.test(mime)) {
    content.push({ type: 'image_url', image_url: { url: 'data:' + mime + ';base64,' + buf.toString('base64') } });
  }
}
let pageImgs = [];
try { pageImgs = ($('Render pages').first().json.images || []).slice(0, 2); } catch (e) { pageImgs = []; }
for (const u of pageImgs) {
  if (typeof u === 'string' && u.startsWith('data:image/') && u.length < 15 * 1024 * 1024) {
    content.push({ type: 'image_url', image_url: { url: u, detail: 'high' } });
  }
}
const schema = { type: 'object', additionalProperties: false,
  required: ['title', 'document_type', 'document_date', 'expires_on', 'summary'],
  properties: {
    title: { type: 'string' },
    document_type: { type: 'string', enum: types },
    document_date: { type: ['string', 'null'] },
    expires_on: { type: ['string', 'null'] },
    summary: { type: 'string' } } };
return [{ json: { body: {
  model: '__JC_MODEL_MAIN__', reasoning_effort: 'low',
  messages: [ { role: 'system', content: __JS:DOCS_PROMPT__ }, { role: 'user', content } ],
  response_format: { type: 'json_schema', json_schema: { name: 'document', strict: true, schema } } },
  from_chat: fromChat, channel: (doc.tags || []).includes(TAGS.telegram) ? 'telegram' : (doc.tags || []).includes(TAGS.whatsapp) ? 'whatsapp' : '__JC_CH_MAIN__' } }];

const clean = s => String(s || '').replace(/[\u0000-\u001f\u007f​-‏‪-‮⁦-⁩]/g, ' ').replace(/\s+/g, ' ').trim();

const r = JSON.parse($input.first().json.choices[0].message.content);
const isDate = s => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s) && !isNaN(Date.parse(s));
const types = $('Get types').first().json.results;
const t = types.find(x => x.name === r.document_type) || types.find(x => x.name === __TJS:doc_type_other__);
const doc = $('Get document').first().json;
const title = clean(r.title).slice(0, 90) || doc.title;
const expires = isDate(r.expires_on) ? r.expires_on : null;
const docDate = isDate(r.document_date) ? r.document_date : null;
const others = (doc.custom_fields || []).filter(f => f.field !== __JC_EXPIRY_FIELD__);
const patch = { title, document_type: t ? t.id : null,
  custom_fields: expires ? [...others, { field: __JC_EXPIRY_FIELD__, value: expires }] : others };
if (docDate) patch.created = docDate;
const summary = clean(r.summary).slice(0, 400);
return [{ json: { doc_id: doc.id, patch, title, type_name: t ? t.name : '', expires, summary,
  note: summary || title } }];

const fill = (s, o) => s.replace(/\{(\w+)\}/g, (_, k) => (k in o ? String(o[k]) : ''));
const DAYS = __JS:DAYS__;
const days = n => (DAYS[new Intl.PluralRules('__JC_LANG__').select(n)] || DAYS.other).replace('{n}', n);
const p = $('Parse').first().json;
const req = $('Build request').first().json;
const today = $now.setZone('__JC_TZ__').startOf('day');
let exp = __TJS:doc_no_expiry__;
if (p.expires) {
  const n = Math.round(DateTime.fromISO(p.expires, { zone: '__JC_TZ__' }).diff(today, 'days').days);
  exp = n < 0 ? fill(__TJS:doc_expired__, { days: days(-n), date: p.expires })
      : fill(__TJS:doc_expires__, { date: p.expires, days: days(n) });
}
const text = fill(__TJS:doc_saved__, { id: p.doc_id }) + '\n' + p.title + '\n' + fill(__TJS:doc_type__, { type: p.type_name }) +
  '\n' + exp + (p.summary ? '\n' + p.summary : '') + '\n__JC_DOCS_URL__/documents/' + p.doc_id + '/details\n' + __TJS:doc_fix__;
const human = { type: 'human', content: req.from_chat ? '[sent a document photo/file on ' + req.channel + ']'
  : '[added a document on the archive website]', additional_kwargs: {}, response_metadata: {} };
const ai = { type: 'ai', content: 'Saved document #' + p.doc_id + ' in the archive: ' + p.title + ', type ' + p.type_name +
  ', expires ' + (p.expires || 'never') + '. ' + p.summary,
  tool_calls: [], additional_kwargs: {}, response_metadata: {}, invalid_tool_calls: [] };
return [{ json: { channel: req.channel, text, human: JSON.stringify(human), ai: JSON.stringify(ai) } }];

const fill = (s, o) => s.replace(/\{(\w+)\}/g, (_, k) => (k in o ? String(o[k]) : ''));
const doc = $('Get document').first().json;
const tags = doc.tags || [];
const error = JSON.stringify($input.first().json || {}).slice(0, 500);
const quota = /insufficient_quota|exceeded your current quota|billing/i.test(error);
const channel = tags.includes(__JC_TAG_TELEGRAM__) ? 'telegram' : tags.includes(__JC_TAG_WHATSAPP__) ? 'whatsapp' : '__JC_CH_MAIN__';
const text = fill(__TJS:doc_failed__, { id: doc.id, reason: quota ? __TJS:doc_failed_quota__ : '',
  link: '__JC_DOCS_URL__/documents/' + doc.id + '/details' });
return [{ json: { channel, text, error } }];
